    """Une un día y una hora de Montevideo y devuelve el inicio como datetime aware."""
    horas, minutos = (int(parte) for parte in hora.split(':'))
    return datetime.combine(dia, time(horas, minutos), tzinfo=reloj.MONTEVIDEO)


