import os
import re
from datetime import date, datetime, time, timedelta
from typing import Annotated, Literal

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException
from pydantic import AfterValidator, AwareDatetime, BaseModel, Field, model_validator

from pulso import correo, db, reloj

router = APIRouter()

DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo']

# Días en que el gimnasio cierra: las series no generan clase ese día.
DIAS_CERRADO = {
    date(2026, 12, 25), date(2027, 1, 1), date(2027, 2, 8), date(2027, 2, 9),
    date(2027, 3, 25), date(2027, 3, 26), date(2027, 5, 1),
}


def _sin_vacio(valor):
    if not valor.strip():
        raise ValueError('no puede estar vacío')
    return valor.strip()


def _hora_valida(valor):
    if not re.fullmatch(r'([01]\d|2[0-3]):[0-5]\d', valor):
        raise ValueError('la hora debe ser HH:MM, de 00:00 a 23:59')
    return valor


Texto = Annotated[str, AfterValidator(_sin_vacio)]
Hora = Annotated[str, AfterValidator(_hora_valida)]


def socio_actual(authorization: str | None = Header(default=None)):
    if not authorization or not authorization.startswith('Bearer '):
        raise HTTPException(401, 'Falta el token')
    socio = db.socio_por_token(authorization.removeprefix('Bearer '))
    if socio is None:
        raise HTTPException(401, 'Token inválido')
    return socio


def admin(x_admin_key: str | None = Header(default=None)):
