class NuevaSerie(BaseModel):
    nombre: Texto
    instructor: Texto
    dia: Dia
    hora: Hora
    duracion_min: int = Field(ge=1)
    cupo: int = Field(ge=1)
    desde: date
    hasta: date

    @model_validator(mode='after')
    def _rango_valido(self):
        if self.hasta < self.desde:
            raise ValueError('hasta no puede ser anterior a desde')
        if (self.hasta - self.desde).days > 366:
            raise ValueError('la serie no puede abarcar más de 366 días')
        return self


@router.post('/admin/series', status_code=201, dependencies=[Depends(admin)])
def crear_serie(datos: NuevaSerie):
    ahora = reloj.ahora()
    inicios = []
    dias = (datos.desde + timedelta(days=n) for n in range((datos.hasta - datos.desde).days + 1))
    for dia in dias:
        if DIAS[dia.weekday()] != datos.dia or dia in DIAS_CERRADO:
            continue
        inicio = _a_inicio(dia, datos.hora)
        if inicio > ahora:
            inicios.append(inicio)
    serie = db.crear_serie(datos.nombre, datos.instructor, datos.dia, datos.hora, datos.duracion_min,
                           datos.cupo, datos.desde.isoformat(), datos.hasta.isoformat(), inicios)
    return ver_serie(serie, db.clases_de_serie(serie['id']))


@router.get('/admin/series/{serie_id}', dependencies=[Depends(admin)])
def obtener_serie(serie_id: int):
    serie = db.serie(serie_id)
    if serie is None:
        raise HTTPException(404, 'No existe la serie')
    return ver_serie(serie, db.clases_de_serie(serie_id))


class CambioSerie(BaseModel):
    desde_clase_id: int
    hora: Hora | None = None
    instructor: Texto | None = None
    cupo: int | None = Field(default=None, ge=1)

    @model_validator(mode='after')
    def _hay_cambios(self):
        campos = ('hora', 'instructor', 'cupo')
        for campo in campos:
            if campo in self.model_fields_set and getattr(self, campo) is None:
                raise ValueError(f'{campo} no puede ser null')
        if all(getattr(self, campo) is None for campo in campos):
            raise ValueError('no hay ningún cambio: indicar hora, instructor o cupo')
        return self


@router.patch('/admin/series/{serie_id}', dependencies=[Depends(admin)])
def cambiar_serie(serie_id: int, datos: CambioSerie):
    serie = db.serie(serie_id)
    if serie is None:
        raise HTTPException(404, 'No existe la serie')
    clases = db.clases_de_serie(serie_id)
    ancla = next((c for c in clases if c['id'] == datos.desde_clase_id), None)
    if ancla is None:
        raise HTTPException(404, 'La clase no es de esta serie')
    ahora = reloj.ahora()
    inicio_ancla = db.a_fecha(ancla['inicio'])
    if inicio_ancla <= ahora:
        raise HTTPException(409, 'La clase ya empezó')

    # Las canceladas no cambian; las programadas desde la clase ancla en adelante sí.
    afectadas = [c for c in clases if c['estado'] == 'programada' and db.a_fecha(c['inicio']) >= inicio_ancla]
    cambios = []
    movidas = []
    for clase in afectadas:
        inicio = db.a_fecha(clase['inicio'])
        nuevo_inicio = None
        if datos.hora is not None:
            dia = inicio.astimezone(reloj.MONTEVIDEO).date()
            calculado = _a_inicio(dia, datos.hora)
            if calculado <= ahora:
                raise HTTPException(409, 'Con la hora nueva, una clase quedaría empezando antes de ahora')
            if calculado != inicio:
                nuevo_inicio = calculado
                movidas.append((clase, calculado))
        if datos.cupo is not None and db.confirmadas(clase['id']) > datos.cupo:
            raise HTTPException(409, 'Con el cupo nuevo, una clase quedaría con más reservas que lugares')
        cambios.append({'id': clase['id'], 'inicio': nuevo_inicio,
                        'instructor': datos.instructor, 'cupo': datos.cupo})

    db.cambiar_serie(serie_id, datos.hora, datos.instructor, datos.cupo, cambios)
    for clase, nuevo_inicio in movidas:
        cuando = correo.fecha_y_hora(nuevo_inicio)
        for socio in db.socios_confirmados(clase['id']):
            correo.enviar(socio['email'], f"Cambio de horario: {clase['nombre']} el {cuando}",
                          f"Hola {socio['nombre']}, {clase['nombre']} cambió de horario: ahora es el {cuando}.")
    return ver_serie(db.serie(serie_id), db.clases_de_serie(serie_id))


@router.post('/admin/clases/{clase_id}/cancelar', dependencies=[Depends(admin)])
def cancelar_clase(clase_id: int):
    clase = db.clase(clase_id)
    if clase is None:
        raise HTTPException(404, 'No existe la clase')
    if clase['estado'] == 'cancelada':
        raise HTTPException(409, 'La clase ya está cancelada')
    inicio = db.a_fecha(clase['inicio'])
    if inicio <= reloj.ahora():
        raise HTTPException(409, 'La clase ya empezó')
    socios = db.cancelar_clase(clase_id)
    cuando = correo.fecha_y_hora(inicio)
    for socio in socios:
        correo.enviar(socio['email'], f"Clase cancelada: {clase['nombre']} el {cuando}",
                      f"Hola {socio['nombre']}, se canceló {clase['nombre']} del {cuando}. "
                      'Te devolvimos el crédito de la reserva.')
    return ver_clase(db.clase(clase_id))

