    ahora = reloj.ahora()
    inicio_ancla = db.a_fecha(ancla['inicio'])
    if inicio_ancla <= ahora:
        raise HTTPException(409, 'La clase ya empezó')

    # Las canceladas no cambian; las programadas desde la clase ancla en adelante sí.
    afectadas = [c for c in clases if c['estado'] == 'programada' and db.a_fecha(c['inicio']) >= inicio_ancla]
    cambios = []
    movidas = []
